func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case AuthStartMsg:
		m.authenticating = true
		return m, m.spinner.Tick

	case AuthResultMsg:
		return m.handleAuthResult(msg)

	case spinner.TickMsg:
		if m.authenticating {
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}

	case CredentialsLoadedMsg:
		return m.handleCredentialsLoaded(msg)

	case ForgeAuthSuccessMsg:
		return m.handleGitLabAuthSuccess(msg)

	case LogoutCompleteMsg:
		return m.handleLogoutComplete()
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleKeyMsg handles keyboard input
func (m *Model) handleKeyMsg(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.authenticating {
	m.authenticating = true
	return m, tea.Batch(m.spinner.Tick, m.authenticate())
}

// handleInputUpdate forwards messages to the active inputs
func (m *Model) handleInputUpdate(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.currentField == fieldToken {
		m.tokenInput, cmd = m.tokenInput.Update(msg)
	}
	return m, cmd
}

// handleAuthResult handles the authentication result
func (m *Model) handleAuthResult(msg AuthResultMsg) (tea.Model, tea.Cmd) {
	log.Printf("AUTH: AuthResultMsg received (Error: %v, User: %q)", msg.Error, msg.User.Username)
	m.authenticating = false
	if msg.Error != nil {
		log.Printf("AUTH: Authentication failed: %v", msg.Error)
		m.error = msg.Error.Error()
		m.success = ""
		m.warning = ""
		return m, nil
	}

	log.Printf("AUTH: Authentication successful for user: %s", msg.User.Username)
	m.error = ""
	m.authenticated = true
	m.user = msg.User
	m.success = "✓ Authenticated as " + msg.User.Username
	m.warning = msg.SaveWarning
	m.currentField = fieldToken
	return m, nil
}

// handleCredentialsLoaded handles the credentials loaded from storage
----
}

// Update handles the form's keys. ↑↓ move between fields, ←→ change the type
// while it is focused, enter confirms and esc cancels (Rule 135); tab does
// nothing here, it belongs to the tabs.
func (f *ForwardForm) Update(msg tea.Msg) (*ForwardForm, tea.Cmd) {
	key, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return f, nil
	}

	switch key.String() {
	case "up":
		f.move(-1)
		return f, nil
	case "down":
		f.move(1)
		return f, nil
	case "esc":
		return f, func() tea.Msg { return ForwardFormCancelMsg{} }
	case "enter":
		return f, f.submit()
	}

	switch f.focused {
	case forwardFieldType:
		switch key.String() {
		case "left":
			f.cycle(-1)
		case "right":
			f.cycle(1)
		}
		return f, nil
	case forwardFieldPort:
		var cmd tea.Cmd
		f.portInput, cmd = f.portInput.Update(msg)
