// the table the view normally shows.
func (f *Finder) Resize(width, height int) {
	f.results.Resize(width, max(height-1, 1))
}

// Update handles input while the prompt is active.
func (f *Finder) Update(msg tea.Msg) (*Finder, tea.Cmd) {
	if key, ok := msg.(tea.KeyPressMsg); ok {
		switch key.String() {
		case "esc":
			return f, func() tea.Msg { return CancelMsg{} }
		case "enter":
			if c, ok := f.results.Selected(); ok {
				k := c.Key
				return f, func() tea.Msg { return ConfirmMsg{Key: k} }
			}
	return &confirmPrompt{title: title, message: message}
}

// Update mirrors components.ConfirmModal's key handling exactly, so the two
// confirmations in this wizard behave like every other one in the app.
func (c *confirmPrompt) Update(msg tea.Msg) (*confirmPrompt, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return c, nil
	}
	switch keyMsg.String() {
	case "left", "right":
		c.yes = !c.yes
		return c, nil
	case "enter", keymap.Space:
		return c, confirmResultCmd(c.yes)
	case "y", "Y":
		return c, confirmResultCmd(true)
	case "n", "N", "esc":
		return c, confirmResultCmd(false)
	}
	return c, nil
}

