func (fb *FilterBar) Update(msg tea.Msg) (FilterBar, tea.Cmd) {
	if !fb.searching {
		return *fb, nil
	}
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return *fb, nil
	}
	switch keyMsg.String() {
	case "esc":
		fb.searching = false
		fb.searchQuery = ""
		fb.searchInput.SetValue("")
		fb.searchInput.Blur()
		return *fb, nil
	case "enter":
		fb.searching = false
		fb.searchQuery = fb.searchInput.Value()
		fb.searchInput.Blur()
		return *fb, nil
	}
	var cmd tea.Cmd
	fb.searchInput, cmd = fb.searchInput.Update(msg)
	fb.searchQuery = fb.searchInput.Value()
	return *fb, cmd
}

